static u32 captured(u32 x) { u32 old=observed; observed=x; return old==x; }
static int edges(u32 a,u32 b,int choose) {
 int n=0; if(a==b) n+=1; if(a!=b) n+=2; if(!(a==b)) n+=4; if(!(a!=b)) n+=8;
 if(choose) { if(a==b) n+=16; } else { if(a!=b) n+=32; } return n;
}
